const esc = (v:unknown) => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const safeImage=(v:unknown)=>{const s=String(v??'');return /^\/assets\/[\w/.-]+$/.test(s)||/^\/api\/ranking-avatar\.php\?server=\d{4,5}&id=\d{5,25}$/.test(s)||/^https:\/\/(assets\.playnccdn\.com|profileimg\.plaync\.com)\//.test(s)?s:'/assets/unavailable.svg';};
