const state:{mine:Character|null;target:Character|null;profile:Character|null;mode:string;view:string;board:string;tasks:any[];map:L.Map|null;layer:L.LayerGroup|null;mapData:any;categories:Set<string>;visited:Set<string>;saved:any[];completed:Set<string>}={mine:null,target:null,profile:null,mode:'pve',view:'home',board:'14',tasks:[],map:null,layer:null,mapData:null,categories:new Set(),visited:new Set(),saved:[],completed:new Set()};
