function guestRead(key:string,fallback:any){try{return JSON.parse(localStorage.getItem(key)||'null')??fallback;}catch{return fallback;}}
function storageRead(key:string,fallback:any){if(!cloud?.user)return guestRead(key,fallback);const r=cloud.records;if(key==='aion-tasks')return Object.keys(r).filter(k=>k.startsWith('task:')&&r[k]).map(k=>k.slice(5));if(key==='aion-map-visited')return Object.keys(r).filter(k=>k.startsWith('visited:')&&r[k]).map(k=>k.slice(8));if(key==='aion-snapshots')return Object.entries(r).filter(([k])=>k.startsWith('reading:')).map(([k,v])=>({...v,id:k.slice(8)})).sort((a,b)=>a.at.localeCompare(b.at));if(key==='aion-farm')return Object.fromEntries(Object.entries(r).filter(([k])=>k.startsWith('farm:')));if(key==='aion-builds')return Object.fromEntries(Object.entries(r).filter(([k])=>k.startsWith('build:')));if(key==='aion-personal')return Object.fromEntries(Object.entries(r).filter(([k])=>k.startsWith('note:')||k.startsWith('route:')));const map:Record<string,string>={'aion-ref-mine':'ref:mine','aion-ref-target':'ref:target','aion-mode':'pref:mode','aion-active-map':'pref:map'};return r[map[key]]??fallback;}
function storageWrite(key:string,value:any){if(cloud?.user){writeCloud(key,value);return;}try{localStorage.setItem(key,JSON.stringify(value));}catch{$('notice').textContent='El navegador no permite guardar el progreso local.';}}
function writeCloud(key:string,value:any){if(!cloud?.user)return;const single:Record<string,string>={'aion-ref-mine':'ref:mine','aion-ref-target':'ref:target','aion-mode':'pref:mode','aion-active-map':'pref:map'};if(single[key]){cloud.write(single[key],value);return;}let prefix='',next:Record<string,any>={};if(key==='aion-tasks'){prefix='task:';next=Object.fromEntries(value.map((k:string)=>['task:'+k,true]));}if(key==='aion-map-visited'){prefix='visited:';next=Object.fromEntries(value.map((k:string)=>['visited:'+(k.includes(':')?k:'2:'+k),true]));}if(key==='aion-snapshots'){prefix='reading:';next=Object.fromEntries(value.map((v:any)=>{v.id||=crypto.randomUUID();return ['reading:'+v.id,v];}));}if(key==='aion-personal'){prefix='personal';next=value;}if(key==='aion-farm'){prefix='farm:';next=value;}if(key==='aion-builds'){prefix='build:';next=value;}const matches=(k:string)=>prefix==='personal'?k.startsWith('note:')||k.startsWith('route:'):k.startsWith(prefix);if(!prefix)return;for(const k of Object.keys(cloud.records).filter(matches))if(!(k in next))cloud.write(k,null,true);for(const [k,v]of Object.entries(next))if(JSON.stringify(v)!==JSON.stringify(cloud.records[k]))cloud.write(k,v);}
state.saved=storageRead('aion-snapshots',[]);state.completed=new Set(storageRead('aion-tasks',[]));state.visited=new Set(storageRead('aion-map-visited',[]).map((k:string)=>k.includes(':')?k:'2:'+k));
