const titles:Record<string,string>={home:'Tu aventura empieza aquí.',pets:'Tu colección, cada día más cerca.',profile:'Tu historia en Atreia.',overview:'Tu build, frente a tu próxima meta.',equipment:'La diferencia está en los detalles.',daevanion:'Traza tu propio destino.',roadmap:'Tu próxima meta empieza aquí.',map:'Atreia tiene mucho por descubrir.',history:'Mira lo lejos que has llegado.',database:'Enciclopedia de AION 2.',events:'Siempre hay una próxima aventura.',ranking:'Poder, progreso y competición.',planner:'Diseña tu próxima build.',damage:'Entiende el daño de tu build.'};
const subtitles:Record<string,string>={home:'',pets:'Tu colección y su avance diario, vinculados al personaje activo.',profile:'Equipo, atributos y progreso del personaje que estás consultando.',overview:'Elige dos personajes y compara sus atributos, equipo y habilidades.',equipment:'Revisa el equipo y las habilidades de tu personaje frente a tu referencia.',daevanion:'Consulta los efectos de cada nodo y prepara tu distribución.',roadmap:'Organiza tus mejoras según tu objetivo y tu presupuesto.',map:'Encuentra criaturas, botines y lugares. Guarda tus rutas de cacería.',history:'Compara las lecturas guardadas de tu personaje.',database:'Busca objetos y criaturas, consulta sus fichas y prepara tus cálculos.',events:'Consulta los próximos eventos y configura tus avisos por región.',ranking:'Explora las clasificaciones por región, servidor y clase.',planner:'Distribuye tus puntos de habilidad y organiza tu barra.',damage:'Estima el efecto de los atributos sobre el daño de tu build.'};
