const characterRequests={mine:0,target:0};
async function selectCharacter(ref:any,which:'mine'|'target',persist=true){
 const token=++characterRequests[which],owner=cloud?.user?.id;
 const c=await request({type:'character',...ref});
 if(cloud?.user?.id!==owner||token!==characterRequests[which]||(!persist&&cloud?.user&&!sameCharacter(cloud.records['ref:'+which],ref)))return;
 if(!c.info?.profile||!c.equipment?.equipment?.equipmentList)throw Error('NCSOFT no devolvió un personaje válido.');
 state[which]=mergeItems(state[which],c);
 if(persist)storageWrite('aion-ref-'+which,ref);
 $('notice').textContent='';$('freshness').textContent='Lectura NCSOFT · '+date(c.fetchedAt);render();
 if(which==='mine'){personalNavigation?.update(state.view);petsView?.refresh();if(state.view==='planner')void planner.followCharacter();if(state.view==='history')renderHistory();}
}
