function countdown(ms:number){const sec=Math.max(0,Math.floor(ms/1000)),days=Math.floor(sec/86400),hours=Math.floor(sec%86400/3600),minutes=Math.floor(sec%3600/60),seconds=sec%60;return days?`${days}d ${hours}h`:hours?`${hours}:${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`:`${minutes}:${String(seconds).padStart(2,'0')}`;}
function renderEvents(){if(!eventsData)return;const now=new Date(),clock=new Date(now.getTime()+eventOffset*60000).toISOString().slice(11,19);$('map-clock').textContent=clock;$('event-clock').textContent=clock+' · Región seleccionada';
 const displayed=eventsData.events.filter((x:any,i:number,all:any[])=>!x.group||all.findIndex(y=>y.group===x.group)===i).map((x:any)=>({...x,next:nextEvent(x,now)})).filter((x:any)=>x.next).sort((a:any,b:any)=>a.next.getTime()-b.next.getTime());
 const rows=displayed.map((x:any)=>{const t=x.next as Date,relative=new Date(t.getTime()+eventOffset*60000).toISOString().slice(11,16),name=x.group==='Shugo Festival'?'Festival Shugo · 11':eventLabel(x);return `<div class="timer-row" style="--event-color:${esc(x.color||'#6386df')}"><i data-lucide="${x.group==='Shugo Festival'?'party-popper':x.category==='boss'?'swords':x.category==='rift'?'sparkles':x.category==='reset'?'refresh-cw':'clock'}"></i><div><b title="${esc(name)}">${esc(name)}</b><small>${relative} · ${t.toLocaleDateString('es-CL',{timeZone:'UTC',day:'2-digit',month:'short'})}${x.mapId?' · Abismo':''}</small></div><strong>${countdown(t.getTime()-now.getTime())}</strong><label class="event-alert-toggle" title="Alerta sonora"><input type="checkbox" data-alert-event="${esc(x.id)}" aria-label="Alerta sonora: ${esc(name)}" ${eventSound.selected.has(x.id)?'checked':''}/><span></span></label>${x.mapId?`<button class="timer-map" data-event-map="${esc(x.id)}" title="Ver lugar en nuestro mapa" aria-label="Ver ${esc(name)} en el mapa">⌖</button>`:''}</div>`;}).join('');
 eventSound.check(displayed.flatMap((x:any)=>{const current=nextEvent(x,new Date(now.getTime()-15000));return [{id:x.id,name:eventLabel(x),at:x.next.getTime()},...(current&&current.getTime()<=now.getTime()?[{id:x.id,name:eventLabel(x),at:current.getTime()}]:[])];}));const focused=(document.activeElement as HTMLElement)?.dataset.alertEvent;$('events-list').innerHTML=rows;$('map-events-list').innerHTML=rows;$('event-ticker').innerHTML=displayed.slice(0,3).map((x:any)=>`<button data-view="events">${esc(eventLabel(x))}<strong>${countdown(x.next.getTime()-now.getTime())}</strong></button>`).join('');
 document.querySelectorAll<HTMLElement>('[data-event-map]').forEach(el=>el.onclick=async()=>{const e=displayed.find((x:any)=>x.id===el.dataset.eventMap);showView('map');await atlas.init();await atlas.load(String(e.mapId),e.lat!==undefined?[e.lat,e.lng]:undefined);});if(focused)document.querySelector<HTMLInputElement>(`#${state.view==='map'?'map-events-list':'events-list'} [data-alert-event="${CSS.escape(focused)}"]`)?.focus({preventScroll:true});if(state.view==='map'||state.view==='events')redrawIcons();
}
setInterval(()=>{if(document.visibilityState==='visible')renderEvents();else if(eventsData){const now=new Date();eventSound.check(eventsData.events.filter((x:any,i:number,all:any[])=>!x.group||all.findIndex(y=>y.group===x.group)===i).flatMap((x:any)=>{const times=[nextEvent(x,now),nextEvent(x,new Date(now.getTime()-15000))];return times.filter(Boolean).map((t:any)=>({id:x.id,name:eventLabel(x),at:t.getTime()}));}));}},1000);
let rankingMode:'power'|'pvp'='power';let ranking:any=null;function refreshRanking(){return rankingMode==='pvp'?loadLegacyRanking():loadRanking();}async function loadLegacyRanking(){rankingMode='pvp';$('ranking-pvp').textContent='Ver clasificación por poder';const token=++rankingVersion;try{ranking ||= await fetch('/data/ranking.json').then(r=>r.json());if(token!==rankingVersion)return;const region=($('ranking-region') as HTMLSelectElement).value,server=($('ranking-server') as HTMLSelectElement).value,clsFilter=($('ranking-class') as HTMLSelectElement).value;const entries=ranking.entries.filter((x:any)=>(region==='all'||(x.ref?.region||'la')===region)&&(!server||String(x.ref?.serverId)===server)&&(!clsFilter||String(x.className).toLowerCase()===clsFilter));$('ranking-description').textContent=ranking.description+' · Lectura '+date(ranking.fetchedAt);const hasScores=entries.some((x:any)=>x.score>0);$('ranking-status').textContent=hasScores?'La fuente ofrece puntos para estos personajes registrados.':'La fuente devuelve puntos JcJ en cero para Sudamérica. Se muestran los personajes registrados sin asignar puestos competitivos.';if(!entries.length)$('ranking-status').textContent='No hay una lectura JcJ publicada para estos filtros.';$('ranking-list').innerHTML='<div class="ranking-row header"><span>#</span><span>Personaje</span><span>Servidor</span><span>Puntuación</span></div>'+entries.map((x:any,i:number)=>{const cls=x.className==='Spiritmaster'?'Elementalist':x.className;return `<div class="ranking-row"><span>${hasScores?(x.rank??i+1):'—'}</span><div class="rank-identity"><div class="rank-portrait">${image(x.profileImage||(cls?'/assets/ui/class_icon_'+cls.toLowerCase()+'.png':'/assets/unavailable.svg'),x.name)}${cls?image('/assets/ui/class_icon_'+cls.toLowerCase()+'.png'):''}</div><div><strong>${esc(x.name)}</strong><small>${esc(classLabels[cls]||cls||'Clase sin dato')}${x.level?' · Nv. '+x.level:''}</small><small class="portrait-provenance">${esc(x.portraitStatus||'Perfil pendiente')}</small></div></div><span>${esc(x.serverName||'—')}</span><span>${hasScores?number(x.score):'Sin dato'}</span></div>`;}).join('');}catch{$('ranking-list').innerHTML='<div class="empty">Ranking no disponible.</div>';}}
function renderDamage(){const attack=Number(($('damage-attack') as HTMLInputElement)?.value||1000),multiplier=Number(($('damage-multiplier') as HTMLInputElement)?.value||200),crit=Number(($('damage-crit') as HTMLInputElement)?.value||20),critDamage=Number(($('damage-critdamage') as HTMLInputElement)?.value||50),amp=Number(($('damage-amp') as HTMLInputElement)?.value||0);const base=attack*multiplier/100*(1+amp/100),avg=base*(1+crit/100*critDamage/100);if($('damage-output'))$('damage-output').innerHTML=`<div class="metric-value">${number(Math.round(avg))}</div><p>Daño medio teórico por impacto</p><div class="metric-note">Impacto normal: ${number(Math.round(base))} · Crítico: ${number(Math.round(base*(1+critDamage/100)))}</div>`;}
document.querySelectorAll<HTMLInputElement>('[data-damage]').forEach(el=>el.oninput=renderDamage);
async function init(){showView(profileRoute()?'profile':names[location.hash.slice(1).split('?')[0]]?location.hash.slice(1).split('?')[0]:'home');document.querySelectorAll<HTMLElement>('[data-view].nav-item').forEach(el=>el.title=names[el.dataset.view!]||el.textContent||'');try{[state.mine,state.target]=await Promise.all(['/data/mine.json','/data/target.json'].map(u=>fetch(u).then(r=>r.json())));initialCharacters={mine:state.mine,target:state.target};render();$('freshness').textContent='Lectura guardada · '+date(state.mine!.fetchedAt);const servers=await fetch('/data/servers.json').then(r=>r.json());$('search-server').innerHTML='<option value="">Todos los servidores</option>'+servers.serverList.map((s:any)=>`<option value="${s.serverId}">${esc(s.serverName)}</option>`).join('');($('search-region') as HTMLSelectElement).onchange=async()=>{try{const d=await request({type:'servers',region:($('search-region') as HTMLSelectElement).value});$('search-server').innerHTML='<option value="">Todos los servidores</option>'+d.serverList.map((s:any)=>`<option value="${s.serverId}">${esc(s.serverName)}</option>`).join('');}catch{$('search-server').innerHTML='<option value="">Todos los servidores</option>';}};const earlyProfile=profileRoute();if(earlyProfile)void openProfile(earlyProfile);for(const key of earlyProfile?[]:['mine','target'] as const){const ref=storageRead('aion-ref-'+key,null);if(ref&&ref.characterId!==state[key]!.ref.characterId){try{await selectCharacter(ref,key);}catch{}}}const shared=profileRoute();if(!shared)showView(names[location.hash.slice(1).split('?')[0]]?location.hash.slice(1).split('?')[0]:'home');void cloud!.init().finally(()=>{sessionReady=true;personalNavigation?.update(state.view);if(pendingPersonalView){if(cloud?.user){const view=pendingPersonalView;pendingPersonalView=null;showView(view);}else document.dispatchEvent(new Event('daeva-sign-in'));}});void loadEvents();if(state.view!=='home'&&state.view!=='profile'&&location.hostname!=='localhost'&&location.hostname!=='127.0.0.1')void refresh();}catch{$('notice').textContent='No se pudieron cargar los personajes. Reintenta la consulta.';}redrawIcons();}
const following=new Set<string>();
function applyCloud(){if(!cloud?.user&&personalViews.has(state.view))showView('home');personalNavigation?.update(state.view);petsView?.refresh();state.saved=storageRead('aion-snapshots',[]);state.completed=new Set(storageRead('aion-tasks',[]));state.visited=new Set(storageRead('aion-map-visited',[]).map((k:string)=>k.includes(':')?k:'2:'+k));state.mode=storageRead('aion-mode','pve');($('mode') as HTMLSelectElement).value=state.mode;if(state.mine&&state.target){renderRoadmap();renderHistory();atlas.refresh();planner.refresh();}for(const key of ['mine','target'] as const){const ref=storageRead('aion-ref-'+key,initialCharacters?.[key]?.ref);if(ref&&!sameCharacter(state[key]?.ref,ref)&&!following.has(key)){following.add(key);void selectCharacter(ref,key,false).catch(e=>{$('notice').textContent='No se pudo cargar tu personaje: '+(e as Error).message;}).finally(()=>{following.delete(key);personalNavigation?.update(state.view);if(key==='mine'&&state.view==='planner')void planner.followCharacter();const desired=cloud?.records['ref:'+key];if(desired&&!sameCharacter(ref,desired))applyCloud();});}}}
cloud=new ProgressCloud(applyCloud,()=>updateAccount());
updateAccount=accountUI(cloud,()=>{for(const [key,fallback]of [['aion-tasks',[]],['aion-map-visited',[]],['aion-snapshots',[]],['aion-personal',{}],['aion-farm',{}],['aion-builds',{}],['aion-ref-mine',initialCharacters?.mine.ref],['aion-ref-target',initialCharacters?.target.ref]] as any){const value=guestRead(key,fallback);if(value!==undefined){if(key==='aion-tasks'||key==='aion-map-visited')writeCloud(key,[...new Set([...storageRead(key,[]),...value])]);else if(key==='aion-snapshots'){const current=storageRead(key,[]);for(const v of value)if(!current.some((s:any)=>s.at===v.at&&s.characterId===v.characterId))current.push(v);writeCloud(key,current.slice(-200));}else if(['aion-personal','aion-farm','aion-builds'].includes(key))writeCloud(key,{...value,...storageRead(key,{})});else if(!storageRead(key,null))writeCloud(key,value);}}applyCloud();},()=>personalNavigation?.selected());
