let profileRequest=0;async function openProfile(ref:any){currentProfileHub?.destroy();currentProfileHub=null;const token=++profileRequest;showView('profile');const host=$('character-profile');host.innerHTML='<div class="panel empty" role="status">Cargando perfil y equipo desde NCSOFT…</div>';try{const c=await request({type:'profile',...ref});if(token!==profileRequest||!profileRoute())return;state.profile=c;$('freshness').textContent='Lectura NCSOFT · '+date(c.fetchedAt);host.innerHTML=standaloneProfile(c,esc,image);bindItems(host);host.querySelectorAll<HTMLElement>('[data-summary-board]').forEach(b=>b.onclick=async()=>{await selectCharacter(ref,'target');boardCharacter='target';state.board=b.dataset.summaryBoard!;showView('daevanion');});host.querySelectorAll<HTMLElement>('[data-gear-group]').forEach(b=>b.onclick=()=>{host.querySelectorAll<HTMLElement>('[data-gear-panel]').forEach(p=>p.hidden=p.dataset.gearPanel!==b.dataset.gearGroup);host.querySelectorAll('[data-gear-group]').forEach(x=>x.classList.toggle('active',x===b));});host.querySelectorAll<HTMLElement>('[data-profile-select]').forEach(b=>b.onclick=async()=>{await selectCharacter(ref,b.dataset.profileSelect as 'mine'|'target');showView('overview');});host.querySelector<HTMLButtonElement>('[data-profile-share]')!.onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+'/'+profileUrl(ref));host.querySelector('[data-profile-message]')!.textContent='Enlace del perfil copiado.';}catch{host.querySelector('[data-profile-message]')!.textContent=location.origin+'/'+profileUrl(ref);}};host.querySelector<HTMLButtonElement>('[data-profile-ranking]')!.onclick=async()=>{showView('ranking');($('ranking-region') as HTMLSelectElement).value=ref.region;await loadRankingServers();($('ranking-server') as HTMLSelectElement).value=String(ref.serverId);void loadRanking();};currentProfileHub=profileHub($('profile-personal'),$('companion-profile'),c,cloud!,showView,esc,()=>state.view==='profile'&&sameCharacter(profileRoute(),c.ref));void profileHistory(c,$('profile-source-history'),esc);redrawIcons();}catch(e){if(token!==profileRequest||!profileRoute())return;host.innerHTML='<div class="panel empty"><p>'+esc((e as Error).name==='TimeoutError'?'NCSOFT tardó en responder. Puedes volver a intentarlo.':(e as Error).message)+'</p><button class="button secondary" data-profile-retry>Reintentar perfil</button>'+reloadButton(e)+'</div>';host.querySelector<HTMLButtonElement>('[data-profile-retry]')!.onclick=()=>void openProfile(ref);}}
let rankingVersion=0;async function loadRanking(){rankingMode='power';$('ranking-pvp').textContent='Ver lectura de puntos JcJ';const token=++rankingVersion;$('ranking-status').textContent='Consultando clasificación por poder…';$('ranking-list').replaceChildren();try{const region=($('ranking-region') as HTMLSelectElement).value;const rankClass=($('ranking-class') as HTMLSelectElement).value,rankServer=($('ranking-server') as HTMLSelectElement).value;const params=new URLSearchParams({region,class:rankClass,server:rankServer});const r=await fetch('/api/rankings.php?'+params);const d=await apiJson(r);if(!r.ok)throw Error(d.error);if(token!==rankingVersion)return;$('ranking-source').setAttribute('href',d.source);$('ranking-description').textContent='Poder de combate · Consulta '+date(d.fetchedAt);$('ranking-status').textContent=d.stale?'La fuente no respondió; mostramos la última lectura disponible.':d.entries.length?`${d.entries.length} personajes · filtros de región, clase y servidor aplicados en la fuente. Cada fila indica su última lectura.`:'No hay personajes para estos filtros.';$('ranking-list').innerHTML='<div class="ranking-row header"><span>#</span><span>Personaje</span><span>Servidor</span><span>Poder / equipo</span></div>'+d.entries.filter((x:any)=>region==='all'||x.region===region).map((x:any)=>{const cls=x.className==='Spiritmaster'?'Elementalist':x.className;return `<div class="ranking-row"><span>${x.rank}</span><div class="rank-identity"><div class="rank-portrait">${image(x.profileImage||'/assets/ui/class_icon_'+cls.toLowerCase()+'.png',x.name)}${image('/assets/ui/class_icon_'+cls.toLowerCase()+'.png')}</div><div><button class="text-button" data-rank-name="${esc(x.name)}" data-rank-region="${esc(x.region)}" data-rank-server="${esc(x.serverName)}">${esc(x.name)}</button><small>${esc(classLabels[cls]||cls)} · Nv. ${x.level}</small></div></div><span>${esc(x.serverName)}<small>${x.readAt?esc(date(x.readAt)):'Sin fecha'}</small></span><span class="rank-metrics"><b>${image('/assets/ui/profile_power_icon.png','Poder')}${number(x.power)}</b><small>${image('/assets/ui/profile_level_icon.png','Equipo')}${x.itemLevel>0?number(x.itemLevel):'—'}</small></span></div>`;}).join('');$('ranking-list').querySelectorAll<HTMLElement>('[data-rank-name]').forEach(b=>b.onclick=async()=>{b.setAttribute('disabled','');try{const x=await request({type:'search',region:b.dataset.rankRegion,keyword:b.dataset.rankName});const matches=(x.list||[]).filter((p:any)=>String(p.name).replace(/<[^>]*>/g,'')===b.dataset.rankName&&p.serverName===b.dataset.rankServer);if(matches.length!==1)throw Error('No hay un perfil oficial único para esta fila. Usa Buscar personaje.');location.hash=profileUrl({region:b.dataset.rankRegion,serverId:matches[0].serverId,characterId:decodeURIComponent(matches[0].characterId)});}catch(e){showApiError($('ranking-status'),e);}finally{b.removeAttribute('disabled');}});}catch(e){showApiError($('ranking-status'),e);}}
let rankingServerVersion=0;async function loadRankingServers(){const version=++rankingServerVersion,region=($('ranking-region') as HTMLSelectElement).value,select=$('ranking-server') as HTMLSelectElement;select.value='';select.disabled=true;select.innerHTML='<option value="">Todos los servidores</option>';if(region==='all'){select.disabled=false;return;}try{const result=await request({type:'servers',region});if(version!==rankingServerVersion)return;select.innerHTML='<option value="">Todos los servidores</option>'+result.serverList.map((s:any)=>`<option value="${esc(s.serverId)}">${esc(s.serverName)}</option>`).join('');}catch{if(version===rankingServerVersion)$('ranking-status').textContent='No se pudo consultar la lista de servidores.';}finally{if(version===rankingServerVersion)select.disabled=false;}}
$('ranking-region').onchange=()=>{rankingVersion++;$('ranking-list').replaceChildren();$('ranking-status').textContent='Consultando servidores de la región…';void loadRankingServers().then(refreshRanking);};$('ranking-server').onchange=()=>void refreshRanking();$('ranking-class').onchange=()=>void refreshRanking();void loadRankingServers();$('ranking-refresh').onclick=()=>void refreshRanking();$('ranking-pvp').onclick=()=>{if(rankingMode==='pvp'){void loadRanking();return;}$('ranking-source').setAttribute('href','https://aion2t.com/leaderboard?region=LA&sort=ranking_points');void loadLegacyRanking();};

